package com.jonaslins.curso;
import jakarta.servlet.*; import jakarta.servlet.http.*; import io.jsonwebtoken.JwtException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; JwtFilter(JwtService jwt,UserRepository users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,java.io.IOException{var h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var u=users.findByEmail(jwt.email(h.substring(7))).orElse(null);if(u!=null){var a=new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities());a.setDetails(new WebAuthenticationDetailsSource().buildDetails(r));SecurityContextHolder.getContext().setAuthentication(a);}}catch(JwtException ignored){}c.doFilter(r,s);} }
